attrs.onChange:
{(e) => {
                      const sel = OFFICIAL_BANK_ACCOUNTS.find(b => b.number === e.target.value)
                      setFormData({
                        ...formData,
                        bank_account_number: e.target.value,
                        bank_account_qb_id: sel?.qbId || formData.bank_account_qb_id,
                      })
                    }}
